package com.codeguardian.controller; import com.codeguardian.service.AIChatService; import com.codeguardian.service.ai.config.AIModelConfigManager; import com.codeguardian.service.ai.dto.AIModelResponse; import lombok.*; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/ai") @RequiredArgsConstructor public class AIModelController{private final AIChatService chat;private final AIModelConfigManager configs;@GetMapping("/models") public List<Map<String,String>> models(){return configs.getAvailableConfigs().stream().map(c->Map.of("provider",c.getProviderName(),"model",Optional.ofNullable(c.getDefaultModel()).orElse(""))).toList();}@PostMapping("/chat") public ResponseEntity<AIModelResponse> chat(@RequestBody ChatRequest r){return ResponseEntity.ok(chat.chat(r.provider,r.prompt));}@Data public static class ChatRequest{private String provider;private String prompt;}}
